-- Custom migration: triggers, RLS, seed data, tsvector
-- This file is hand-written (not generated by drizzle-kit)

-- 1. Enable pgcrypto extension (may already exist from init-db.sql)
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 2. State transition trigger
CREATE OR REPLACE FUNCTION validate_task_transition()
RETURNS TRIGGER AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM task_valid_transitions
    WHERE from_state = OLD.state AND to_state = NEW.state
  ) THEN
    RAISE EXCEPTION 'Invalid task state transition from % to %', OLD.state, NEW.state;
  END IF;
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER task_state_transition_check
  BEFORE UPDATE ON tasks
  FOR EACH ROW
  WHEN (OLD.state IS DISTINCT FROM NEW.state)
  EXECUTE FUNCTION validate_task_transition();

-- 3. Audit table RLS
ALTER TABLE audit_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_entries FORCE ROW LEVEL SECURITY;

CREATE POLICY audit_no_update ON audit_entries
  AS RESTRICTIVE FOR UPDATE USING (false);
CREATE POLICY audit_no_delete ON audit_entries
  AS RESTRICTIVE FOR DELETE USING (false);
CREATE POLICY audit_allow_insert ON audit_entries
  FOR INSERT WITH CHECK (true);
CREATE POLICY audit_allow_select ON audit_entries
  FOR SELECT USING (true);

