-- Cancelled from all non-terminal states
INSERT INTO task_valid_transitions (from_state, to_state)
SELECT s.state, 'cancelled'::task_state
FROM unnest(ARRAY[
  'created','needs_clarification','assigned','in_progress','paused',
  'evidence_ready','changes_requested','approved','pr_created',
  'external_checks_pending','addressing_review_feedback','external_blocked','merge_ready'
]::task_state[]) AS s(state)
ON CONFLICT DO NOTHING;

-- 5. tsvector generated column on code_symbols (Drizzle Kit can't generate this)
ALTER TABLE code_symbols ADD COLUMN search_vector tsvector
  GENERATED ALWAYS AS (
    to_tsvector('simple', coalesce(symbol_name, '') || ' ' || coalesce(file_path, ''))
  ) STORED;
CREATE INDEX code_symbols_search_vector_idx ON code_symbols USING gin (search_vector);

